solution:
.pass {
  margin: 24px;
  font-family: system-ui, sans-serif;
  color: #18181b;
}

.code {
  font-size: 40px;
  font-weight: 800;
}

.city {
  font-size: 13px;
  color: #52525b;
}

.label {
  font-size: 11px;
  color: #71717a;
}

.arrow {
  font-size: 24px;
  color: #f97316;
}

/* ---- Solution ---- */
.pass {
  display: grid;
  grid-template-columns: 1fr 140px;
  width: 560px;
  filter: drop-shadow(0 6px 12px rgb(0 0 0 / 0.18));
}

.main {
  padding: 24px;
  border-radius: 12px 0 0 12px;
  background:
    radial-gradient(circle at 100% 0, transparent 12px, #ffffff 13px) top / 100% 51% no-repeat,
    radial-gradient(circle at 100% 100%, transparent 12px, #ffffff 13px) bottom / 100% 51% no-repeat;
}

.stub {
  display: grid;
  place-items: center;
  align-content: center;
  gap: 4px;
  padding: 24px;
  border-left: 2px dashed #ffffff;
  border-radius: 0 12px 12px 0;
  background:
    radial-gradient(circle at 0 0, transparent 12px, #f97316 13px) top / 100% 51% no-repeat,
    radial-gradient(circle at 0 100%, transparent 12px, #f97316 13px) bottom / 100% 51% no-repeat;
  background-origin: border-box;
  color: #ffffff;
}

.route {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.stop {
  display: grid;
}

.details {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 12px;
  margin-top: 20px;
  padding-top: 16px;
  border-top: 1px solid #e4e4e7;
}

.detail {
  display: grid;
  gap: 2px;
}

.label {
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.value {
  font-weight: 700;
}

.stub .label {
  color: #ffedd5;
}

.seat {
  font-size: 36px;
  font-weight: 800;
}
